// MUTATION HV-ANCHOR implementation red NMH_MUTATE=IMPL-HBACK: the test is built against a private copy of the design outside the repository in which bit 6 of the H field of VHPOSR is inverted, so that the H field falls back twice inside a line (make test-<core> NANOMIG=<copy>, then NMH_ONLY=HV): TG68K FAIL, fx68k FAIL; no other line moves on the copy.
// MUTATION PR-1c stimulus impossible no selector: unfalsifiable at this boundary: the pages give no stimulus that removes refresh, so no program can make this line red; its falsifier is the implementation record IMPL-NOREF below.
// MUTATION PR-1c implementation red NMH_MUTATE=IMPL-NOREF: the test is built against a private copy of the design outside the repository in which no refresh access is made (make test-<core> NANOMIG=<copy>, then NMH_ONLY=REF); the pages give no stimulus that removes refresh: TG68K FAIL, fx68k FAIL; other lines that move on the copy: R2-UR PASS to FAIL, R2-XCHK-REF PASS to FAIL, PR-2a PASS to FAIL, P1 PASS to NOT GRADED, P1-RE PASS to NOT GRADED, P1-RN PASS to NOT GRADED, P2 PASS to NOT GRADED, P1P2-JOINT PASS to NOT GRADED.
// MUTATION P6-E4 stimulus impossible no selector: unfalsifiable at this boundary: the pages give no stimulus that reorders the free cycles of a line, so no program can make this line red; its falsifier is the implementation record IMPL-E4 below.
// MUTATION P6-E4 implementation red NMH_MUTATE=IMPL-E4: the test is built against a private copy of the design outside the repository in which the bit-plane pointer comes out on the first free cycle and the sprite pointer on the second and third (make test-<core> NANOMIG=<copy>, then NMH_ONLY=U): TG68K FAIL, fx68k FAIL; other lines that move on the copy: P6-AGG PASS to FAIL.
// MUTATION P6-E4 implementation green NMH_MUTATE=IMPL: the test is built against a private copy of the design outside the repository that implements the page sentences of 7.5 (make test-<core> NANOMIG=<copy>); normal run: TG68K PASS, fx68k PASS.
// ---- header end

#include "s7r_p1.h"
#include "s7r_p3.h"

using namespace s7r;

int main(int argc, char** argv) {
    g_dir = argc > 1 ? argv[1] : ".";
    g_mutate = std::getenv("NMH_MUTATE");
    const char* only = std::getenv("NMH_ONLY");   // NMH_ONLY=HV,P8 restricts a run to the named parts
    std::printf("CORE: %s\n", cap_core().c_str());
    if (g_mutate) std::printf("NMH_MUTATE=%s\n", g_mutate);
    Checks ck;
    auto want = [&](const char* p) {
        if (!only) return true;
        std::string l = std::string(",") + only + ",";
        return l.find(std::string(",") + p + ",") != std::string::npos;
    };
    // the claims section 1 of the specification declines: one line per id with the reason
    {
        const char* reg[] = {"strequ", "strvbl", "strhor"};
        struct Why { const char* c; const char* t; };
        const Why why[] = {
            {"c1", "address of a strobe: it exists only on the RGA bus, which no port of nanomig.v shows (SPECIFICATION.md 1.1)"},
            {"c2", "S, strobe: that a write has no data bits could only be seen through an effect of the write, and no page gives one (SPECIFICATION.md 1.1)"},
            {"c4", "&, register used by DMA channel only: it says who uses the address and predicts nothing a test can observe (SPECIFICATION.md 1.1)"},
            {"c5", "~, not writable by the Coprocessor unless COPCON bit 1 is set: an effective write can be told from an ineffective one only by its effect, and no page gives an effect for this address (SPECIFICATION.md 1.1)"},
            {"c6", "function: what the address signals exists only on the RGA bus, and no page ties it to an output a test sees (SPECIFICATION.md 1.1)"},
        };
        for (const char* r : reg)
            for (const char* who : {"opus", "sol"})
                for (const Why& w : why)
                    ck.record(std::string("DECLINED ") + who + ":AA-" + r + "." + w.c + ": " + w.t);
        for (const char* who : {"opus", "sol"})
            ck.record(std::string("DECLINED ") + who + ":AA-refptr.c4: &, register used by DMA channel only: the quantifier 'only', that no processor uses the register, cannot be made observable, and a claim is graded whole or not at all (SPECIFICATION.md 1.2)");
        for (const char* who : {"opus", "sol"})
            ck.record(std::string("DECLINED ") + who + ":AA-refptr.c5: ~, not writable by the Coprocessor unless COPCON bit 1 is set: the claim is universal (every legal Copper write, whenever the bit is clear); the package makes one MOVE at one beam position with two data words and grades that observation on P1P2-JOINT without the id (SPECIFICATION.md 1.2)");
    }
    Shared sh;
    if (want("HV") || want("P8") || want("REF") || want("U")) run_shared(ck, sh);
    if (want("REF")) run_refptr(ck, sh);
    if (want("U")) run_uhres(ck, sh);
    if (want("P8")) run_p8(ck, sh.hv);
    std::printf("%d passed, %d failed\n", ck.passed, ck.failed);
    return ck.failed == 0 ? 0 : 1;
}
